create extension if not exists pgcrypto;
create type public.app_role as enum ('owner','admin','manager','editor','commenter','viewer');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null unique,full_name text,avatar_url text,role public.app_role not null default 'viewer',onboarding_completed boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.plans(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,price_inr integer not null,storage_gb integer not null,member_limit integer not null,features jsonb not null default '{}',active boolean not null default true,created_at timestamptz not null default now());
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,owner_id uuid not null references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.workspaces(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,slug text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,slug));
create table public.workspace_roles(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,role public.app_role not null,permissions jsonb not null default '{}',unique(workspace_id,name));
create table public.workspace_members(workspace_id uuid references public.workspaces(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role public.app_role not null default 'viewer',invited_by uuid references public.profiles(id),joined_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table public.subscriptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_id uuid not null references public.plans(id),razorpay_subscription_id text unique,status text not null check(status in('trialing','active','past_due','cancelled','expired')),current_period_start timestamptz,current_period_end timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,slug text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,slug));
create table public.resources(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,resource_type text not null,storage_key text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.activity_logs(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,actor_id uuid references public.profiles(id) on delete set null,action text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.settings(id uuid primary key default gen_random_uuid(),owner_type text not null check(owner_type in('user','organization','workspace')),owner_id uuid not null,key text not null,value jsonb not null default '{}',updated_at timestamptz not null default now(),unique(owner_type,owner_id,key));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,actor_id uuid references public.profiles(id) on delete set null,event text not null,ip inet,user_agent text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.storage_usage(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,bytes_used bigint not null default 0,b2_bucket text not null,b2_prefix text not null,measured_at timestamptz not null default now());
create table public.analytics_events(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete set null,workspace_id uuid references public.workspaces(id) on delete cascade,event text not null,properties jsonb not null default '{}',created_at timestamptz not null default now());
create index on public.organizations(owner_id);create index on public.projects(workspace_id);create index on public.resources(workspace_id,project_id);create index on public.workspaces(organization_id);create index on public.workspace_members(user_id);create index on public.notifications(user_id,read_at);create index on public.activity_logs(workspace_id,created_at desc);create index on public.audit_logs(organization_id,created_at desc);create index on public.storage_usage(workspace_id,measured_at desc);create index on public.analytics_events(workspace_id,created_at desc);
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger projects_touch before update on public.projects for each row execute function public.touch_updated_at();create trigger resources_touch before update on public.resources for each row execute function public.touch_updated_at();create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_at();create trigger organizations_touch before update on public.organizations for each row execute function public.touch_updated_at();create trigger workspaces_touch before update on public.workspaces for each row execute function public.touch_updated_at();create trigger subscriptions_touch before update on public.subscriptions for each row execute function public.touch_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name,avatar_url) values(new.id,new.email,new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'avatar_url'); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.current_workspace_role(workspace_uuid uuid) returns public.app_role language sql stable security definer as $$ select role from public.workspace_members where workspace_id=workspace_uuid and user_id=auth.uid() $$;
create or replace function public.log_activity(workspace_uuid uuid, action_text text, metadata_json jsonb default '{}') returns uuid language plpgsql security definer as $$ declare new_id uuid; begin insert into public.activity_logs(workspace_id,actor_id,action,metadata) values(workspace_uuid,auth.uid(),action_text,metadata_json) returning id into new_id; return new_id; end $$;
alter table public.projects enable row level security;alter table public.resources enable row level security;alter table public.profiles enable row level security;alter table public.plans enable row level security;alter table public.organizations enable row level security;alter table public.workspaces enable row level security;alter table public.workspace_roles enable row level security;alter table public.workspace_members enable row level security;alter table public.subscriptions enable row level security;alter table public.notifications enable row level security;alter table public.activity_logs enable row level security;alter table public.settings enable row level security;alter table public.audit_logs enable row level security;alter table public.storage_usage enable row level security;alter table public.analytics_events enable row level security;
create policy projects_member_read on public.projects for select using(public.current_workspace_role(workspace_id) is not null);create policy projects_editor_write on public.projects for all using(public.current_workspace_role(workspace_id) in('owner','admin','manager','editor')) with check(public.current_workspace_role(workspace_id) in('owner','admin','manager','editor'));create policy resources_member_read on public.resources for select using(public.current_workspace_role(workspace_id) is not null);create policy resources_editor_write on public.resources for all using(public.current_workspace_role(workspace_id) in('owner','admin','manager','editor')) with check(public.current_workspace_role(workspace_id) in('owner','admin','manager','editor'));create policy profiles_self on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());create policy plans_read on public.plans for select using(active);create policy org_member_read on public.organizations for select using(exists(select 1 from public.workspaces w join public.workspace_members m on m.workspace_id=w.id where w.organization_id=id and m.user_id=auth.uid()));create policy workspace_member_read on public.workspaces for select using(exists(select 1 from public.workspace_members m where m.workspace_id=id and m.user_id=auth.uid()));create policy workspace_admin_write on public.workspaces for all using(public.current_workspace_role(id) in ('owner','admin','manager')) with check(public.current_workspace_role(id) in ('owner','admin','manager'));
create policy member_read on public.workspace_members for select using(user_id=auth.uid() or public.current_workspace_role(workspace_id) in('owner','admin','manager'));create policy member_admin_write on public.workspace_members for all using(public.current_workspace_role(workspace_id) in('owner','admin','manager')) with check(public.current_workspace_role(workspace_id) in('owner','admin','manager'));
create policy notifications_self on public.notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy activity_member_read on public.activity_logs for select using(workspace_id is null or public.current_workspace_role(workspace_id) is not null);create policy settings_self on public.settings for all using(owner_id=auth.uid() or exists(select 1 from public.workspace_members where workspace_id=owner_id and user_id=auth.uid())) with check(owner_id=auth.uid());create policy audit_org_read on public.audit_logs for select using(exists(select 1 from public.workspaces w where w.organization_id=organization_id and public.current_workspace_role(w.id) in('owner','admin','manager')));create policy storage_member_read on public.storage_usage for select using(public.current_workspace_role(workspace_id) is not null);create policy analytics_insert on public.analytics_events for insert with check(user_id=auth.uid());create policy analytics_member_read on public.analytics_events for select using(workspace_id is null or public.current_workspace_role(workspace_id) in('owner','admin','manager'));
